'''Interfaces and protocols for decomposed components.'''
from abc import ABC, abstractmethod


class SearchStrategy(ABC):
    """Interface for building search URLs and parsing result pages."""

    @abstractmethod
    def build_search_url(self, keywords, arguments):
        """Build the search URL from keywords and arguments."""
        pass

    @abstractmethod
    def extract_image_urls(self, page_source, limit, arguments):
        """Extract image URLs from a Google Images result page."""
        pass


class Downloader(ABC):
    """Interface for downloading images and handling network I/O."""

    @abstractmethod
    def download_page(self, url):
        """Download raw HTML page content."""
        pass

    @abstractmethod
    def download_extended_page(self, url, chromedriver):
        """Download extended page using Selenium."""
        pass


class ImageSaver(ABC):
    """Interface for saving images to the filesystem."""

    @abstractmethod
    def download_image(self, url, file_path, filename, socket_timeout):
        """Download a single image and save it."""
        pass

    @abstractmethod
    def create_directories(self, keywords, output_directory, image_directory, no_directory):
        """Create the directory structure for saving images."""
        pass

    @abstractmethod
    def get_file_size(self, file_path):
        """Get the size of a file."""
        pass
